conn = get_conn()
total = 0
for numero, enunciado in QUESTOES.items():
    rows = conn.execute("""
        SELECT id FROM questoes
        WHERE escola='ITA' AND ano=2024 AND fase='1'
        AND disciplina='ingles' AND numero=?
    """, (numero,)).fetchall()
    
    if rows:
        for row in rows:
            conn.execute("UPDATE questoes SET enunciado=? WHERE id=?", (enunciado, row['id']))
            total += 1
            print(f"Q{numero}: atualizado")
    else:
        # Insere questão faltante
        conn.execute("""
            INSERT INTO questoes (id, escola, disciplina, ano, numero, fase, enunciado, alternativas, gabarito, nivel, tags, tem_imagem)
            VALUES (?, 'ITA', 'ingles', 2024, ?, '1', ?, '[]', '', 'dificil', '["ingles"]', 0)
        """, (str(uuid.uuid4()), numero, enunciado))
        total += 1
        print(f"Q{numero}: inserida")

conn.commit()
conn.close()
print(f"\nTotal: {total} questões processadas")
